  getGetCurrentUserQueryKey,
  getGetOrderQueryKey, getGetProductAlternativesQueryKey, getGetProductQueryKey, getGetStoreDashboardQueryKey,
  getListAdminAlertsQueryKey, getListInventoryRiskQueryKey, getListOrdersQueryKey, getListStoreOrdersQueryKey,
  getListProductsQueryKey, getListStoreInventoryQueryKey,
  useCheckOrderRisk, useCreateOrder, useGetAdminDashboard, useGetCurrentUser,
